/**
 * Fictional account scenarios for the Relationship Snapshot simulation.
 *
 * ALL FIGURES ARE INVENTED, and so is every person named in this file.
 *
 * The ACCOUNT names are real firms, at the request of the people demonstrating
 * this prototype: a sales audience recognises the accounts it works with, and
 * "Kestrel Fund Services" tells them nothing. Nothing behind those names is
 * real — every figure is generated by data/mock-repo.js, no live Salesforce,
 * billing, transaction or Jira system is contacted, and every surface that
 * shows a figure also says the data is simulated.
 *
 * The CALASTONE staff are real colleagues, named so the demo shows the right
 * owner for each account. The CLIENT contacts are not, and must not be: those
 * are individuals attributed to real firms, which is the one thing on this
 * page that should never look real.
 *
 * A scenario is a *profile* — it shapes what the generator produces rather than
 * hard-coding every number, so each account stays internally coherent while
 * remaining fully deterministic.
 */

/**
 * The Calastone relationship managers. Real colleagues.
 *
 * `region` carries what each of them covers rather than where they sit: the
 * card prints it after the title, and a coverage line is both true and useful
 * where an invented city would be neither.
 */
export const STAFF = [
  { name: 'Scott Maxam', title: 'Relationship Manager', region: 'Platforms & Distributors' },
  { name: 'Neil Marns', title: 'Relationship Manager', region: 'Fund Managers & Transfer Agents' },
  { name: 'Paul Elflain', title: 'Relationship Manager', region: 'ETFs & HSBC' },
  { name: 'Nicki Pelling', title: 'Relationship Manager', region: 'Allfunds & other accounts' },
];

const BY_NAME = Object.freeze(Object.fromEntries(STAFF.map((p) => [p.name, p])));

/** Named accounts that belong to someone regardless of how they are segmented. */
const NAMED_ACCOUNTS = Object.freeze([
  { token: 'hsbc', rm: 'Paul Elflain' },
  { token: 'allfunds', rm: 'Nicki Pelling' },
]);

/** Segment → owner. Anything unlisted falls to Nicki, who holds "and others". */
const BY_SEGMENT = Object.freeze({
  platform: 'Scott Maxam',
  distributor: 'Scott Maxam',
  'fund manager': 'Neil Marns',
  'asset manager': 'Neil Marns',
  'transfer agent': 'Neil Marns',
  etf: 'Paul Elflain',
  'etf issuer': 'Paul Elflain',
});

/**
 * Who owns an account.
 *
 * Unlike every other field in the simulation this is NOT drawn from the seeded
 * RNG — an account's owner is a fact about the account, so the same segment
 * always produces the same manager. A named-account rule outranks the segment,
 * which is how HSBC stays with Paul despite being a transfer agent.
 *
 * @param {{accountName?: string, segment?: string}} profile
 */
export function rmFor(profile) {
  const name = String(profile?.accountName || '');
  for (const rule of NAMED_ACCOUNTS) {
    if (name.toLowerCase().includes(rule.token)) return BY_NAME[rule.rm];
  }
  const segment = String(profile?.segment || '').trim().toLowerCase();
  return BY_NAME[BY_SEGMENT[segment]] || BY_NAME['Nicki Pelling'];
}

